@pytest.mark.parametrize("tileset", ("", "tileset.rts"), ids=("internal","external"))
def test_parse_rmp(tileset:str):
	rmp_bytes = _map_internal_tileset_bytes if tileset == "" else _map_external_tileset_bytes
	f = BytesIO(rmp_bytes)
	rmp = SphereMap()
	rmp.filePath = "test.rmp"
	rmp._parseFileData(f)

	assert rmp.startX == 215
	assert rmp.startY == 55
	assert rmp.startLayer == 1
	assert rmp.startDirection == MapDirections.North
	assert rmp.strings[MapString.TilesetFile] == tileset
	assert rmp.strings[MapString.MusicFile] == __musicFile
	assert rmp.strings[MapString.ScriptFile] == ""
	assert rmp.strings[MapString.EntryScript] == __entryScript
	assert rmp.strings[MapString.ExitScript] == __exitScript
	assert rmp.strings[MapString.NorthScript] == __northScript
	assert rmp.strings[MapString.EastScript] == __eastScript
	assert rmp.strings[MapString.SouthScript] == __southScript
	assert rmp.strings[MapString.WestScript] == __westScript

	assert len(rmp.layers) == 2
	for l in range(len(rmp.layers)):
		layer = rmp.layers[l]
		expectedLayer = __expectedLayers[l]
		assert layer.name == expectedLayer["name"]
		assert layer.width == expectedLayer["width"]
		assert layer.height == expectedLayer["height"]
		assert layer.flags == expectedLayer["flags"]
		assert layer.parallaxX == expectedLayer["parallaxX"]
		assert layer.parallaxY == expectedLayer["parallaxY"]
		assert layer.scrollingX == expectedLayer["scrollingX"]
		assert layer.scrollingY == expectedLayer["scrollingY"]
		assert layer.numSegments == expectedLayer["numSegments"]
		assert layer.reflective == expectedLayer["reflective"]
		
		assert len(layer.tiles) == layer.width * layer.height
		assert layer.tiles == expectedLayer["tiles"]

		for s in range(len(layer.segments)):
			assert layer.segments[s].x1 == expectedLayer["segments"][s].x1
			assert layer.segments[s].y1 == expectedLayer["segments"][s].y1
			assert layer.segments[s].x2 == expectedLayer["segments"][s].x2
			assert layer.segments[s].y2 == expectedLayer["segments"][s].y2

	for e in range(len(rmp.entities)):
		entity = rmp.entities[e]
		expectedEntity = __expectedEntities[e]
		assert entity.mapX == expectedEntity["mapX"]
		assert entity.mapY == expectedEntity["mapY"]
		assert entity.layer == expectedEntity["layer"]
		assert entity.type == expectedEntity["type"]
		match entity.type:
			case 1:
				assert entity.name == expectedEntity["name"]
				assert entity.spritesetFilename == expectedEntity["spritesetFilename"]
				assert entity.scripts == expectedEntity["scripts"]
			case 2:
				assert entity.script == expectedEntity["script"]

	for z in range(len(rmp.zones)):
		zone = rmp.zones[z]
		expectedZone = __expectedZones[z]
		assert zone.x1 == expectedZone["x1"]
		assert zone.y1 == expectedZone["y1"]
		assert zone.x2 == expectedZone["x2"]
		assert zone.y2 == expectedZone["y2"]
		assert zone.layer == expectedZone["layer"]
		assert zone.reactivateInNumSteps == expectedZone["reactivateInNumSteps"]

	if tileset != "":
		rts_file = BytesIO(_tileset_bytes)
		rts_file.seek(0)
		rmp.tileset = Tileset.fromReader(rts_file, "")

	assert rmp.tileset
	assert rmp.tileset.tileWidth == __expectedTileset["tileWidth"]
	assert rmp.tileset.tileHeight == __expectedTileset["tileHeight"]
	assert rmp.tileset.tileBPP == __expectedTileset["tileBPP"]
	assert rmp.tileset.compression == __expectedTileset["compression"]
	assert rmp.tileset.hasObstructions == __expectedTileset["hasObstructions"]
	for t in range(len(rmp.tileset.tiles)):
		tile = rmp.tileset.tiles[t]
		expectedTile = __expectedTiles[t]
		assert tile.animated == expectedTile["animated"]
		assert tile.nextTile == expectedTile["nextTile"]
		assert tile.delay == expectedTile["delay"]
		assert tile.blocked == expectedTile["blocked"]
		assert tile.name == expectedTile["name"]
		assert tile.obstructions == expectedTile["obstructions"]